// IsBreached reports whether password's SHA-256 hash matches a known
// breached/compromised password. This is a stronger signal than the
// common-password wordlist check: it means this exact password has shown
// up in real-world breach corpora, not just that it looks weak.
func IsBreached(password string) bool {
	if password == "" {
		return false
	}
	sum := sha256.Sum256([]byte(password))
	_, found := breachedHashSet[hex.EncodeToString(sum[:])]
	return found
}
